import{_ as l,W as t,s as o,u,ah as c,I as p,w as a,Z as e,A as i}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const v=JSON.parse('{"title":"一窥你安装的 Linux 软件包 | LCTT x X-CMD","titleTemplate":false,"description":"一窥你安装的 Linux 软件包 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"一窥你安装的 Linux 软件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一窥你安装的 Linux 软件包 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20171214 Peeking into your Linux packages","title":"一窥你安装的 Linux 软件包","tag":"201810"},"relativePath":"201810/20171214 Peeking into your Linux packages.md","filePath":"[post].md"}'),d={name:"201810/20171214 Peeking into your Linux packages.md"};function r(g,n,b,m,k,h){const s=t("Link");return u(),o("div",null,[n[13]||(n[13]=c(`<h1 id="一窥你安装的-linux-软件包" tabindex="-1">一窥你安装的 Linux 软件包 <a class="header-anchor" href="#一窥你安装的-linux-软件包" aria-label="Permalink to 一窥你安装的 Linux 软件包">​</a></h1><blockquote><p>这些最有用的命令可以让你了解安装在你的 Debian 类的 Linux 系统上的包的情况。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2017/12/christmas-packages-100744371-large.jpg" alt=""></p><p>你有没有想过你的 Linux 系统上安装了几千个软件包？ 是的，我说的是“千”。 即使是相当一般的 Linux 系统也可能安装了上千个软件包。 有很多方法可以获得这些包到底是什么包的详细信息。</p><p>首先，要在基于 Debian 的发行版（如 Ubuntu）上快速得到已安装的软件包数量，请使用 <code>apt list --installed</code>， 如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ apt list --installed | wc -l</span></span>
<span class="line"><span>2067</span></span></code></pre></div><p>这个数字实际上多了一个，因为输出中包含了 “Listing ...” 作为它的第一行。 这个命令会更准确：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ apt list --installed | grep -v &quot;^Listing&quot; | wc -l</span></span>
<span class="line"><span>2066</span></span></code></pre></div><p>要获得所有这些包的详细信息，请按以下方式浏览列表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ apt list --installed | more</span></span>
<span class="line"><span>Listing...</span></span>
<span class="line"><span>a11y-profile-manager-indicator/xenial,now 0.1.10-0ubuntu3 amd64 [installed]</span></span>
<span class="line"><span>account-plugin-aim/xenial,now 3.12.11-0ubuntu3 amd64 [installed]</span></span>
<span class="line"><span>account-plugin-facebook/xenial,xenial,now 0.12+16.04.20160126-0ubuntu1 all [installed]</span></span>
<span class="line"><span>account-plugin-flickr/xenial,xenial,now 0.12+16.04.20160126-0ubuntu1 all [installed]</span></span>
<span class="line"><span>account-plugin-google/xenial,xenial,now 0.12+16.04.20160126-0ubuntu1 all [installed]</span></span>
<span class="line"><span>account-plugin-jabber/xenial,now 3.12.11-0ubuntu3 amd64 [installed]</span></span>
<span class="line"><span>account-plugin-salut/xenial,now 3.12.11-0ubuntu3 amd64 [installed]</span></span></code></pre></div><p>这需要观察很多细节 —— 特别是让你的眼睛在所有 2000 多个文件中徘徊。 它包含包名称、版本等，以及更多但并不是以最易于我们人类解析的显示信息。 <code>dpkg-query</code> 使得描述更容易理解，但这些描述会塞满你的命令窗口，除非窗口非常宽。 因此，为了让此篇文章更容易阅读，下面的数据显示已经分成了左右两侧。</p><p>左侧：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ dpkg-query -l | more</span></span>
<span class="line"><span>Desired=Unknown/Install/Remove/Purge/Hold</span></span>
<span class="line"><span>| Status=Not/Inst/Conf-files/Unpacked/halF-conf/Half-inst/trig-aWait/Trig-pend</span></span>
<span class="line"><span>|/ Err?=(none)/Reinst-required (Status,Err: uppercase=bad)</span></span>
<span class="line"><span>||/ Name                                                 Version                                      </span></span>
<span class="line"><span>+++-==============================================-=================================-</span></span>
<span class="line"><span>ii  a11y-profile-manager-indicator                 0.1.10-0ubuntu3                              </span></span>
<span class="line"><span>ii  account-plugin-aim                             3.12.11-0ubuntu3                             </span></span>
<span class="line"><span>ii  account-plugin-facebook                        0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>ii  account-plugin-flickr                          0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>ii  account-plugin-google                          0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>ii  account-plugin-jabber                          3.12.11-0ubuntu3                             </span></span>
<span class="line"><span>ii  account-plugin-salut                           3.12.11-0ubuntu3                             </span></span>
<span class="line"><span>ii  account-plugin-twitter                         0.12+16.04.20160126-0ubuntu1                 </span></span>
<span class="line"><span>rc  account-plugin-windows-live                    0.11+14.04.20140409.1-0ubuntu2</span></span></code></pre></div><p>右侧：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Architecture Description</span></span>
<span class="line"><span>============-=====================================================================</span></span>
<span class="line"><span>amd64        Accessibility Profile Manager - Unity desktop indicator</span></span>
<span class="line"><span>amd64        Messaging account plugin for AIM</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - facebook</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - flickr</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon</span></span>
<span class="line"><span>amd64        Messaging account plugin for Jabber/XMPP</span></span>
<span class="line"><span>amd64        Messaging account plugin for Local XMPP (Salut)</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - twitter</span></span>
<span class="line"><span>all          GNOME Control Center account plugin for single signon - windows live</span></span></code></pre></div><p>每行开头的 <code>ii</code> 和 <code>rc</code> 名称（见上文“左侧”）是包状态指示符。 第一个字母表示包的预期状态：</p><ul><li><code>u</code> -- 未知</li><li><code>i</code> -- 安装</li><li><code>r</code> -- 移除/反安装</li><li><code>p</code> -- 清除（也包括配置文件）</li><li><code>h</code> -- 保留</li></ul><p>第二个代表包的当前状态：</p><ul><li><code>n</code> -- 未安装</li><li><code>i</code> -- 已安装</li><li><code>c</code> -- 配置文件（只安装了配置文件）</li><li><code>U</code> -- 未打包</li><li><code>F</code> -- 半配置（出于某些原因配置失败）</li><li><code>h</code> -- 半安装（出于某些原因配置失败）</li><li><code>W</code> -- 等待触发（该包等待另外一个包的触发器）</li><li><code>t</code> -- 待定触发（该包被触发）</li></ul><p>在通常的双字符字段末尾添加的 <code>R</code> 表示需要重新安装。 你可能永远不会碰到这些。</p><p>快速查看整体包状态的一种简单方法是计算在不同状态中包含的包的数量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ dpkg-query -l | tail -n +6 | awk &#39;{print $1}&#39; | sort | uniq -c</span></span>
<span class="line"><span> 2066 ii</span></span>
<span class="line"><span> 134 rc</span></span></code></pre></div><p>我从上面的 <code>dpkg-query</code> 输出中排除了前五行，因为这些是标题行，会混淆输出。</p><p>这两行基本上告诉我们，在这个系统上，应该安装了 2066 个软件包，而 134 个其他的软件包已被删除，但留下了配置文件。 你始终可以使用以下命令删除程序包的剩余配置文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dpkg --purge xfont-mathml</span></span></code></pre></div><p>请注意，如果程序包二进制文件和配置文件都已经安装了，则上面的命令将两者都删除。</p><hr>`,27)),p("p",null,[n[1]||(n[1]=a("via: ")),e(s,{href:"https://www.networkworld.com/article/3242808/linux/peeking-into-your-linux-packages.html"},{default:i(()=>n[0]||(n[0]=[a("https://www.networkworld.com/article/3242808/linux/peeking-into-your-linux-packages.html")])),_:1})]),p("p",null,[n[5]||(n[5]=a("作者：")),e(s,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>n[2]||(n[2]=[a("Sandra Henry-Stocker")])),_:1}),n[6]||(n[6]=a(" 译者：")),e(s,{href:"https://github.com/Flowsnow"},{default:i(()=>n[3]||(n[3]=[a("Flowsnow")])),_:1}),n[7]||(n[7]=a(" 校对：")),e(s,{href:"https://github.com/wxy"},{default:i(()=>n[4]||(n[4]=[a("wxy")])),_:1})]),p("p",null,[n[10]||(n[10]=a("本文由 ")),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>n[8]||(n[8]=[a("LCTT")])),_:1}),n[11]||(n[11]=a(" 原创编译，")),e(s,{href:"https://linux.cn/"},{default:i(()=>n[9]||(n[9]=[a("Linux中国")])),_:1}),n[12]||(n[12]=a(" 荣誉推出"))])])}const C=l(d,[["render",r]]);export{v as __pageData,C as default};
